#!/bin/bash
set -euo pipefail

CONTAINERFILE_PATH="$AGENTEVAL_WORKSPACE_DIR/.agenteval-agenteval-codex.Containerfile"
cat > "$CONTAINERFILE_PATH" <<'CONTAINERFILE'
FROM docker.io/library/node:22-bookworm
RUN apt-get update && apt-get install -y --no-install-recommends bash git procps ca-certificates && rm -rf /var/lib/apt/lists/*
RUN npm install -g @openai/codex@0.147.0
RUN mkdir -p /usr/local/lib/agenteval /workspace/.agenteval/codex
RUN node -e "require('node:fs').writeFileSync('/usr/local/lib/agenteval/agenteval-codex.mjs', Buffer.from('', 'base64'))" && chmod 0755 /usr/local/lib/agenteval/agenteval-codex.mjs && ln -s /usr/local/lib/agenteval/agenteval-codex.mjs /usr/local/bin/agenteval-codex
WORKDIR /workspace
CMD ["codex", "--help"]
CONTAINERFILE

node - "$CONTAINERFILE_PATH" <<'NODE'
const fs = require("node:fs");
const containerfile = fs.readFileSync(process.argv[2], "utf8");
const adapter = {
  agent_id: process.env.AGENTEVAL_AGENT_ID,
  name: "OpenAI Codex CLI",
  description: "Pinned @openai/codex npm agent with native JSONL retention and canonical event wrapper",
  format_version: 1,
  install_type: "npm",
  image: "localhost/agenteval-" + process.env.AGENTEVAL_AGENT_ID + ":latest",
  source_repo: null,
  source_ref: null,
  containerfile,
  default_provider: process.env.AGENTEVAL_PROVIDER,
  default_model: process.env.AGENTEVAL_MODEL,
  command: {
    argv: ["agenteval-codex", "{{prompt}}", "{{model}}", "{{provider}}", "{{run_id}}"],
    env: {"OPENAI_BASE_URL":"https://api.neuralwatt.com/v1"},
    cwd: "/workspace",
    timeout_ms: 900000,
  },
  derive_connection_check: true,
  configure: null,
  provider_config: {"credentialEnv":{"nuralwatt":{"OPENAI_API_KEY":"NEURALWATT_API_KEY"},"openai":{"OPENAI_API_KEY":"OPENAI_API_KEY"}}},
  parser_kind: "canonical-jsonl",
  parser_config: null,
  evidence: {
    paths: [".agenteval/codex"],
    required_paths: [".agenteval/codex"],
  },
  shared: true,
  enabled: true,
};
process.stdout.write(JSON.stringify(adapter));
NODE
